from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class File_activate(EmssimCommand):
    def __init__(self, method="file_activate", timeout=60, rpc_connection_name='localRPC'):
        super(File_activate, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(File_activate, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "Validation completed, activating plan file"):
                self._ret['validation'] = "completed"
            elif (data["msg"] == "Activation completed"):
                self._ret['activation'] = "completed"
            elif (data["msg"] == "Activation Errors"):
                self._ret['table'] = data["tables"]
                self._ret['activation_error'] = data["errors"]
        elif ("status" in data):
            self._ret["status"] = data["status"]
